case REMOTE_EVENT_STATE:
    /* Tagged as status on purpose. This is the bridge's bounded status line,
     * which for a talking agent holds a truncated slice of the current reply
     * — successive snapshots then look like a torn transcript with pieces
     * missing. The transcript itself is complete and lives in the link; read
     * it with 'rreply'. */
    syslog(LOG_INFO, "[%s] status: %s\n", TAG, text != NULL ? text : "");
    break;

case REMOTE_EVENT_AGENT_OUTPUT:
    /* The link keeps the bounded transcript; this is only a trace so a
     * long turn is observable while it runs. */
    syslog(LOG_DEBUG, "[%s] agent output (%u bytes)\n", TAG,
        (unsigned)(text != NULL ? strlen(text) : 0));
    break;

input.new_string:
case REMOTE_EVENT_STATE:
    /* A status line and nothing else: what the agent is doing, never what it
     * said. The bridge holds to the same rule on its side, so this reports
     * "Agent working", a tool name, or "Agent replying" — the reply itself
     * arrives as REMOTE_EVENT_TURN_TRANSCRIPT once the turn ends. */
    syslog(LOG_INFO, "[%s] status: %s\n", TAG, text != NULL ? text : "");
    break;

case REMOTE_EVENT_AGENT_OUTPUT:
    /* Chunks are traced by size only. Printing them as they arrive is what
     * made a reply unreadable: they land every few tens of milliseconds and
     * split mid-sentence. The link accumulates them instead. */
    syslog(LOG_DEBUG, "[%s] agent output (%u bytes)\n", TAG,
        (unsigned)(text != NULL ? strlen(text) : 0));
    break;

case REMOTE_EVENT_TURN_TRANSCRIPT: {
    const char* line = text;

    if (line == NULL) {
        break;
    }

    /* One line per call rather than one call for the whole reply: every line
     * keeps the usual syslog prefix, and nothing here depends on how much a
     * single syslog write can carry. */
    syslog(LOG_INFO, "[%s] reply:\n", TAG);
    while (*line != '\0') {
        const char* end = strchr(line, '\n');
        int length = end != NULL ? (int)(end - line) : (int)strlen(line);

        syslog(LOG_INFO, "[%s]   %.*s\n", TAG, length, line);
        if (end == NULL) {
            break;
        }
        line = end + 1;
    }
    break;
}

