} else if (message.type === "agent_output") {
  if (message.turn_id !== reply.turnId) { reply.turnId = message.turn_id; reply.text = ""; reply.seq = 0; reply.gap = false; }
  if (message.output_seq <= reply.seq) return;
  /* QoS 0 can drop a chunk. A hole is worth saying out loud rather than
   * silently splicing the surviving halves together. */
  if (reply.seq && message.output_seq !== reply.seq + 1) reply.gap = true;
  reply.seq = message.output_seq;
  reply.text += message.text;
